  1	import React, { useEffect, useMemo, useRef, useState } from 'react';
  2	import { useIntl } from 'react-intl';
  3	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
  4	import { ChevronLeftIcon, ChevronRightIcon } from '../../icons';
  5	
  6	type ColourVariant = {
  7	  /** SFCC variation value (e.g. 'lilac', 'raspberry') */
  8	  value: string;
  9	  /** Display name for label and aria-label (e.g. 'Lilac', 'Raspberry') */
 10	  name: string;
 11	  /**
 12	   * Resolved URL of the swatch-viewType product image for this colour.
 13	   * When absent the colour is not surfaced to the shopper at all — no swatch renders (AC5).
 14	   */
 15	  imageUrl?: string;
 16	  /**
 17	   * Whether this colour is orderable. SDK's VariationAttributeValue.orderable is
 18	   * `boolean | undefined` — treat undefined as true (orderable) when mapping.
 19	   * A non-orderable colour is not surfaced to the shopper at all — no swatch renders (AC5).
 20	   */
 21	  orderable: boolean;
 22	};
 23	
 24	/** A colour that passed the AC5 gate: guaranteed to carry a resolved swatch image. */
 25	type OfferedColourVariant = ColourVariant & { imageUrl: string };
 26	
 27	/** Figma: pagination appears if there are more than 4 swatches. */
 28	const PAGE_SIZE = 4;
 29	
 30	/**
 31	 * Swatch images render into a 47px-wide box, so request a DIS-scaled image rather than the
 32	 * full-resolution product shot (AGENTS.md > Performance > Images: "Never render
 33	 * full-resolution images at thumbnail size"). 96px covers the 47px box at 2x DPR; q=60
 34	 * matches the quality the base retail app's image-gallery already requests.
 35	 */
 36	const SWATCH_IMAGE_WIDTH = 96;
 37	/** 96px at the 36/55 aspect ratio the swatch box uses — keeps the intrinsic ratio honest. */
 38	const SWATCH_IMAGE_HEIGHT = 147;
 39	const SWATCH_IMAGE_QUALITY = 60;
 40	
 41	const ZIMM_COLOUR_SWATCHES_RECIPE = 'ZimmColourSwatches';
 42	
 43	/**
 44	 * Appends SFCC Dynamic Image Service sizing params to a resolved swatch URL. Equivalent to
 45	 * the `[?sw={width}&q=60]` bracket notation the base app feeds to DynamicImage, but for a
 46	 * fixed-size swatch there is only one width to serve, so DynamicImage's responsive
 47	 * srcSet/sizes machinery would be dead weight. Picks the separator defensively — `link`
 48	 * (the fallback when `disBaseLink` is absent) can already carry a query string.
 49	 */
 50	const sizedSwatchUrl = (url: string) => {
 51	  if (url.startsWith('data:')) return url;
 52	  return `${url}${url.includes('?') ? '&' : '?'}sw=${SWATCH_IMAGE_WIDTH}&q=${SWATCH_IMAGE_QUALITY}`;
 53	};
 54	
 55	type ColourSwatchesProps = {
 56	  /** All available colour variants for this product */
 57	  variants: readonly ColourVariant[];
 58	  /** Currently selected colour value — omit or pass undefined if none selected */
 59	  selectedValue?: string;
 60	  /** Called when the shopper clicks or keyboard-selects a swatch */
 61	  onSelect: (value: string) => void;
 62	};
 63	
 64	/**
 65	 * Renders a radiogroup of colour swatches for the PDP. Pure UI — receives fully
 66	 * resolved props from the parent page; does not call any SDK hooks.
 67	 */
 68	const ColourSwatches = ({ variants, selectedValue, onSelect }: ColourSwatchesProps) => {
 69	  const { formatMessage } = useIntl();
 70	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCHES_RECIPE, {});
 71	  const swatchRefs = useRef<(HTMLButtonElement | null)[]>([]);
 72	  // pendingFocusIndexRef: position within the page to focus after a page change triggered
 73	  // by keyboard navigation. Set in handleKeyDown, consumed in the page useEffect.
 74	  const pendingFocusIndexRef = useRef<number | null>(null);
 75	  const [page, setPage] = useState(0);
 76	
 77	  // AC5: a colour is only offered if it has a resolved swatch image AND is orderable.
 78	  // An unavailable/disabled colour is withheld entirely rather than shown in a disabled
 79	  // state — confirmed by the BA 2026-08-21, superseding the earlier `opacity: 0.4` reading.
 80	  // Memoised to avoid repeated filter passes on every render and to keep pageCount stable
 81	  // across renders where variants hasn't changed.
 82	  // Type predicate so `imageUrl` narrows to `string` in the render below — Array.filter
 83	  // alone would leave it `string | undefined` and force an assertion at the img src.
 84	  const swatchVariants = useMemo(
 85	    () => variants.filter((v): v is OfferedColourVariant => Boolean(v.imageUrl) && v.orderable),
 86	    [variants],
 87	  );
 88	  // Always-current ref so the auto-advance effect can read swatchVariants without depending
 89	  // on it — if it depended on swatchVariants, any parent re-render that creates a new
 90	  // variants array identity would reset a chevron-navigated page back to the selected
 91	  // colour's page. The ref is updated synchronously during render, before effects run.
 92	  const swatchVariantsRef = useRef(swatchVariants);
 93	  swatchVariantsRef.current = swatchVariants;
 94	  // AC1: single colour → text label only, no swatch row.
 95	  const showSwatches = swatchVariants.length > 1;
 96	
 97	  const pageCount = Math.ceil(swatchVariants.length / PAGE_SIZE);
 98	  const showPagination = swatchVariants.length > PAGE_SIZE;
 99	  const pagedVariants = swatchVariants.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
100	
101	  // Resolve from swatchVariants (not variants) so a withheld colour's name is never shown
102	  // in the label — AC5 requires withheld colours not to be surfaced at all.
103	  const selectedName = swatchVariants.find((v) => v.value === selectedValue)?.name;
104	  // AC1: when there is exactly one offered colour, show its name even before a selection
105	  // is made. Keyed off swatchVariants, not variants — a product whose other colours were
106	  // all withheld is a single-colour product as far as the shopper can tell.
107	  const labelName = selectedName ?? (swatchVariants.length === 1 ? swatchVariants[0]?.name : undefined);
108	
109	  // Stable primitive derived from the offered set's content (not identity). Changes when a
110	  // colour gains/loses its image or orderable status; stays the same when a parent re-render
111	  // produces a new variants array reference with the same logical values.
112	  const swatchVariantsKey = JSON.stringify(swatchVariants.map((v) => v.value));
113	
114	  // When the selected colour is on a different page (e.g. deep link with ?color=), advance
115	  // to that page automatically so the selected swatch is always visible.
116	  // Deps: selectedValue + swatchVariantsKey — the key re-fires when the offered set changes
117	  // content so page is recalculated; swatchVariants is still read via ref so identity-only
118	  // parent re-renders do not reset a chevron-navigated page.
119	  useEffect(() => {
120	    if (selectedValue === undefined) return;
121	    const globalIndex = swatchVariantsRef.current.findIndex((v) => v.value === selectedValue);
122	    if (globalIndex === -1) return;
123	    setPage(Math.floor(globalIndex / PAGE_SIZE));
124	  // eslint-disable-next-line react-hooks/exhaustive-deps
125	  }, [selectedValue, swatchVariantsKey]);
126	
127	  // Clamp page to a valid range when swatchVariants shrinks (e.g. variants prop changes).
128	  useEffect(() => {
129	    setPage((p) => Math.min(p, Math.max(0, pageCount - 1)));
130	  }, [pageCount]);
131	
132	  // After a page change triggered by keyboard navigation, focus the pending swatch.
133	  useEffect(() => {
134	    if (pendingFocusIndexRef.current !== null) {
135	      swatchRefs.current[pendingFocusIndexRef.current]?.focus();
136	      pendingFocusIndexRef.current = null;
137	    }
138	  }, [page]);
139	
140	  const handleKeyDown = (e: React.KeyboardEvent) => {
141	    if (swatchVariants.length === 0) return;
142	
143	    // Navigate across the full swatchVariants array (not just the current page) so
144	    // arrow keys wrap correctly and auto-advance pages at page boundaries.
145	    const currentIndex = swatchVariants.findIndex((v) => v.value === selectedValue);
146	    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
147	    const isBackward = e.key === 'ArrowLeft' || e.key === 'ArrowUp';
148	    if (!isForward && !isBackward) return;
149	
150	    e.preventDefault();
151	
152	    let nextIndex: number;
153	    if (currentIndex === -1) {
154	      // Nothing selected: forward → first, backward → last.
155	      // Must NOT fall through to modulo maths — with currentIndex === -1,
156	      // backward would compute (len - 2), landing on the second-to-last swatch.
157	      nextIndex = isForward ? 0 : swatchVariants.length - 1;
158	    } else {
159	      nextIndex = isForward
160	        ? (currentIndex + 1) % swatchVariants.length
161	        : (currentIndex - 1 + swatchVariants.length) % swatchVariants.length;
162	    }
163	
164	    onSelect(swatchVariants[nextIndex].value);
165	
166	    const nextPage = Math.floor(nextIndex / PAGE_SIZE);
167	    const nextIndexOnPage = nextIndex % PAGE_SIZE;
168	
169	    if (nextPage !== page) {
170	      // Page change: set pending focus so the useEffect above applies it after re-render.
171	      setPage(nextPage);
172	      pendingFocusIndexRef.current = nextIndexOnPage;
173	    } else {
174	      swatchRefs.current[nextIndexOnPage]?.focus();
175	    }
176	  };
177	
178	  // Tab stop: the selected swatch if it's on the current page; otherwise the first swatch
179	  // on the current page, keeping a single tab stop inside the radiogroup at all times.
180	  const selectedOnCurrentPage = pagedVariants.some((v) => v.value === selectedValue);
181	
182	  return (
183	    // 44px top spacing (var(--zimm-scale-1100)) is owned here so the gap is consistent
184	    // regardless of whether modelInfo or styleCode is present in the parent PdpProductInfo.
185	    <chakra.div __css={styles.container} sx={{ marginTop: 'var(--zimm-scale-1100)' }} data-testid="pdp-colour-swatches">
186	      <chakra.div __css={styles.labelRow}>
187	        {/* caption-strong: caption textStyle + fontWeight medium (no captionStrong key in typography.ts) */}
188	        <chakra.span __css={styles.label}>
189	          {formatMessage({ id: 'colour_swatches.label', defaultMessage: 'Colour:' })}
190	        </chakra.span>
191	        {labelName && (
192	          // testid rather than a role: this is a bare span with no semantics of its own,
193	          // and E2E needs to assert the selected colour's name independently of the swatches.
194	          <chakra.span __css={styles.selectedName} data-testid="pdp-colour-selected-name">
195	            {labelName}
196	          </chakra.span>
197	        )}
198	        {showPagination && (
199	          // Chevron buttons: 24×24px hit area, 16×16px icon — Figma node 40000307-13867.
200	          <chakra.div
201	            __css={styles.paginationGroup}
202	            role="group"
203	            aria-label={formatMessage({ id: 'colour_swatches.pagination.group_label', defaultMessage: 'Colour swatch pages' })}
204	          >
205	            <chakra.button
206	              __css={styles.chevronButton}
207	              type="button"
208	              aria-label={formatMessage({ id: 'colour_swatches.pagination.previous', defaultMessage: 'Previous colours' })}
209	              onClick={() => setPage((p) => Math.max(0, p - 1))}
210	              disabled={page === 0}
211	            >
212	              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
213	              <ChevronLeftIcon boxSize="16px" />
214	            </chakra.button>
215	            <chakra.button
216	              __css={styles.chevronButton}
217	              type="button"
218	              aria-label={formatMessage({ id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' })}
219	              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
220	              disabled={page === pageCount - 1}
221	            >
222	              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
223	              <ChevronRightIcon boxSize="16px" />
224	            </chakra.button>
225	          </chakra.div>
226	        )}
227	      </chakra.div>
228	
229	      {showSwatches && (
230	        <chakra.div
231	          __css={styles.swatchGroup}
232	          role="radiogroup"
233	          aria-label={formatMessage({ id: 'colour_swatches.group.label', defaultMessage: 'Colour' })}
234	          onKeyDown={handleKeyDown}
235	        >
236	          {pagedVariants.map((variant, index) => {
237	            const { value, name, imageUrl } = variant;
238	            const isSelected = value === selectedValue;
239	            const isTabStop = isSelected || (!selectedOnCurrentPage && index === 0);
240	
241	            return (
242	              <chakra.button
243	                key={value}
244	                __css={styles.swatch}
245	                type="button"
246	                ref={(el: HTMLButtonElement | null) => {
247	                  swatchRefs.current[index] = el;
248	                }}
249	                role="radio"
250	                aria-checked={isSelected}
251	                aria-label={name}
252	                tabIndex={isTabStop ? 0 : -1}
253	                data-testid={`pdp-colour-swatch-${value}`}
254	                // Selected swatch paints above siblings — zIndex driven by selection state.
255	                sx={{ zIndex: isSelected ? 1 : undefined }}
256	                onClick={() => onSelect(value)}
257	              >
258	                {/* imageUrl is typed `string` here via OfferedColourVariant, not merely assumed non-null. */}
259	                <chakra.div __css={styles.swatchImage}>
260	                  <img
261	                    src={sizedSwatchUrl(imageUrl)}
262	                    alt=""
263	                    loading="lazy"
264	                    width={SWATCH_IMAGE_WIDTH}
265	                    height={SWATCH_IMAGE_HEIGHT}
266	                    style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
267	                  />
268	                </chakra.div>
269	                {isSelected && <chakra.div __css={styles.selectedIndicator} />}
270	              </chakra.button>
271	            );
272	          })}
273	        </chakra.div>
274	      )}
275	    </chakra.div>
276	  );
277	};
278	
279	export type { ColourVariant, ColourSwatchesProps };
280	export { ColourSwatches };
281	export default ColourSwatches;

