204	          >
205	            <chakra.button
206	              __css={styles.chevronButton}
207	              type="button"
208	              aria-label={formatMessage({ id: 'colour_swatches.pagination.previous', defaultMessage: 'Previous colours' })}
209	              onClick={() => setPage((p) => Math.max(0, p - 1))}
210	              disabled={page === 0}
211	            >
212	              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
213	              <ChevronLeftIcon boxSize="16px" />
214	            </chakra.button>
215	            <chakra.button
